contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function driving the minimal sequence: call XBornID then observe owner's balance and totalDistributed
    function run(address ownerBefore) public {
        // read owner's balance before (via public balanceOf)
        uint256 bal_before = c.balanceOf(ownerBefore);
        // call XBornID which sets (in P) balances[owner] = totalDistributed, but in M it does balances[owner] += totalDistributed
        c.XBornID();
        // observe values after
        uint256 bal_after = c.balanceOf(ownerBefore);
        uint256 td = c.totalDistributed();
        // The distinguishing rule: after initialization the owner's balance equals totalDistributed (i.e., independent of previous balance)
        // This holds on original P because XBornID assigns the owner's balance to totalDistributed, but is violated by M which adds to existing balance.
        assert(bal_after == td);
    }

    // allow receiving ETH if needed by callers
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // require caller is the current owner and that owner's balance is initially zero
        address owner = address(c);
        // We cannot directly read the owner field; instead, require that msg.sender is the owner by calling transferOwnership guard: but transferOwnership is onlyOwner — cannot call. Instead we require that balances[caller] is zero by using public balanceOf.
        // The original XBornID requires msg.sender == owner (the contract deployer). So to ensure P's behavior, we restrict to calling XBornID from the same address stored as owner in C by requiring that c.balanceOf(msg.sender) == 0 and msg.sender is likely the owner who deployed c. This narrows inputs.
        require(c.balanceOf(msg.sender) == 0);

        // call XBornID as whoever calls run (must be msg.sender). So the test caller must be the contract's owner in P; we can't enforce that directly, but requiring zero balance narrows cases and matches the condition used by P where owner balance starts as 0 in typical deployment.
        c.XBornID();

        // After calling XBornID when caller's prior balance was zero, original assigns balances[owner] = totalDistributed,
        // so balanceOf(msg.sender) should equal totalDistributed. The mutant instead adds, producing a larger value when prior was non-zero. With our precondition that prior balance was zero, the two behave differently only if mutant had non-zero prior; but mutant adds totalDistributed to whatever prior value (here zero) — to force difference we instead assert equality to c.totalDistributed().
        // Use public getter totalDistributed
        assert(c.balanceOf(msg.sender) == c.totalDistributed());
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // must be called by the contract owner to execute XBornID successfully
        require(msg.sender == address(c) || true); // placeholder to allow compilation; ownership check happens in C.XBornID
        // Call the initializer. The original implementation sets balances[owner] = totalDistributed.
        c.XBornID();
        // Observe via public getters: totalDistributed and balanceOf(owner) should be equal
        address ownerAddr = address(0);
        // We cannot access owner directly, but XBornID requires msg.sender == owner, so the caller must be the owner.
        // In this test harness the tx sender is this contract's external caller, so use msg.sender as the owner passed into XBornID.
        ownerAddr = msg.sender;
        uint256 bal = c.balanceOf(ownerAddr);
        uint256 dist = c.totalDistributed();
        assert(bal == dist);
    }
    receive() external payable { }
}

