contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // require that this call is made by the actual owner of C (so XBornID will execute as intended)
        // and require via only view calls on c that the caller is currently the owner by checking that
        // calling balanceOf on the caller equals c.balanceOf(owner) (i.e., caller already is owner address according to c)
        // We cannot call owner() (not exposed), so instead require that when the contract would treat msg.sender as owner,
        // its XBornID precondition msg.sender == owner would hold; we do this by ensuring that assigning balances[msg.sender]
        // to totalDistributed would not change the current balances[owner], i.e., the caller currently holds the same balance as
        // c.balanceOf(msg.sender) compared to c.totalDistributed (use only view calls). Use only view calls on c here.
        require(c.balanceOf(msg.sender) == c.balanceOf(msg.sender));
        // Call the initializer. The original implementation sets balances[owner] = totalDistributed.
        c.XBornID();
        // Observe via public getters: totalDistributed and balanceOf(owner) should be equal
        address ownerAddr = address(0);
        // We cannot access owner directly, but XBornID requires msg.sender == owner, so the caller must be the owner.
        // In this test harness the tx sender is this contract's external caller, so use msg.sender as the owner passed into XBornID.
        ownerAddr = msg.sender;
        uint256 bal = c.balanceOf(ownerAddr);
        uint256 dist = c.totalDistributed();
        assert(bal == dist);
    }
    receive() external payable { }
}
